<?php
$form=isset($form)&&is_array($form)?$form:array();$selectedArea=isset($form['SpbbID'])?(int)$form['SpbbID']:($branches?(int)$branches[0]['SpbbID']:0);$places=array();$prefill=array();foreach($branches as $b)$places[(int)$b['SpbbID']]=$b['Area']??$b['SpbbName'];$defaults=$this->pipeline_bunker_letter->defaults($places[$selectedArea]??'Padangbai');$form+=$defaults;
foreach($vessels as $v){$prefill[(int)$v['VesselID']]=array();foreach(array('VesselName','Flag','GrossTonnage','VesselType','CompanyName','MainTank','DailyTank') as $k)$prefill[(int)$v['VesselID']][$k]=(string)($v[$k]??'');}
$value=function($key,$fallback='')use($form){return isset($form[$key])&&is_scalar($form[$key])?(string)$form[$key]:$fallback;};
?>
<div class="content-wrapper"><section class="content-header"><h1>Surat Permohonan Pengawasan Bunker</h1></section><section class="content"><?php if($error): ?><div class="alert alert-danger"><?= html_escape($error) ?></div><?php endif; ?>
<form method="post" id="bunker-form"><?php $this->load->view('pipeline/billing_token'); ?><div class="box box-primary"><div class="box-header with-border"><h3 class="box-title">Data Surat</h3></div><div class="box-body"><div class="row">
<div class="col-sm-6 form-group"><label for="bunker-area">Area</label><select id="bunker-area" name="SpbbID" class="form-control" required><?php foreach($branches as $b): ?><option value="<?= (int)$b['SpbbID'] ?>" <?= $selectedArea===(int)$b['SpbbID']?'selected':'' ?>><?= html_escape($b['SpbbName']) ?></option><?php endforeach; ?></select></div>
<div class="col-sm-6 form-group"><label for="bunker-vessel">Pilih Kapal / Perusahaan</label><select id="bunker-vessel" name="VesselID" class="form-control" required><option value="">Pilih dari Basic Data</option><?php foreach($vessels as $v): ?><option data-area="<?= (int)$v['SpbbID'] ?>" value="<?= (int)$v['VesselID'] ?>" <?= (int)$value('VesselID')===(int)$v['VesselID']?'selected':'' ?>><?= html_escape($v['VesselName'].' / '.$v['CompanyName']) ?></option><?php endforeach; ?></select></div>
<div class="col-sm-6 form-group"><label for="bunker-number">Nomor Surat Otomatis</label><input id="bunker-number" class="form-control" readonly placeholder="Pilih area, kapal dan tanggal surat"><small id="bunker-number-help" aria-live="polite">Nomor final ditetapkan saat surat disimpan.</small></div>
<div class="col-sm-3 form-group"><label for="bunker-RequestDate">Tanggal Surat</label><input id="bunker-RequestDate" type="date" name="RequestDate" class="form-control" value="<?= html_escape($value('RequestDate',date('Y-m-d'))) ?>" required></div><div class="col-sm-3 form-group"><label for="bunker-Place">Tempat Surat</label><input id="bunker-Place" name="Place" maxlength="200" class="form-control" value="<?= html_escape($value('Place')) ?>" required></div>
<div class="col-sm-6 form-group"><label for="bunker-AttachmentText">Lampiran</label><input id="bunker-AttachmentText" name="AttachmentText" maxlength="100" class="form-control" value="<?= html_escape($value('AttachmentText')) ?>" required></div><div class="col-sm-6 form-group"><label>Perihal</label><input class="form-control" value="Surat Permohonan Pengawasan Bunker" readonly></div>
<div class="col-sm-6 form-group"><label for="bunker-Recipient">Kepada Yth.</label><textarea id="bunker-Recipient" name="Recipient" maxlength="500" rows="3" class="form-control" required><?= html_escape($value('Recipient')) ?></textarea></div><div class="col-sm-6 form-group"><label for="bunker-RecipientPlace">Kota Tujuan Surat (Di-)</label><input id="bunker-RecipientPlace" name="RecipientPlace" maxlength="200" class="form-control" value="<?= html_escape($value('RecipientPlace')) ?>" required><label for="bunker-PortName" style="margin-top:10px">Pelabuhan Penyeberangan (narasi surat)</label><input id="bunker-PortName" name="PortName" maxlength="200" class="form-control" value="<?= html_escape($value('PortName')) ?>" required></div></div></div></div>
<div class="box box-primary"><div class="box-header with-border"><h3 class="box-title">Rincian Kapal dan Pengisian</h3></div><div class="box-body"><p class="text-muted">Nama kapal dan perusahaan mengikuti master. Data teknis terisi dari master dan dapat disesuaikan untuk surat ini.</p><div class="row"><?php $i=0;foreach($letter_fields as $k=>$field):$locked=in_array($k,array('VesselName','CompanyName'),true); ?><div class="col-sm-6 form-group"><label for="bunker-<?= $k ?>"><?= ++$i ?>. <?= html_escape($field[0]) ?><?= $k==='PlannedLiters'?' (liter)':'' ?></label><input data-bunker-field="<?= $i ?>" id="bunker-<?= $k ?>" name="<?= $k ?>" class="form-control" type="<?= $field[1] ?>" maxlength="<?= $field[2] ?>" value="<?= html_escape($value($k,$k==='FillingDate'?date('Y-m-d'):'')) ?>" <?= $locked?'readonly':'' ?> <?= $k==='PlannedLiters'?'min="0.001" max="1000000000" step="0.001"':'' ?> required><?php if($k==='MainTank'||$k==='DailyTank'||$k==='RemainingFuel'): ?><small>Isi beserta satuan, misalnya <?= $k==='RemainingFuel'?'600 Liter, 500 Liter':($k==='MainTank'?'18.600 liter':'1.750 Liter') ?>.</small><?php endif; ?></div><?php endforeach; ?></div></div></div>
<div class="box"><div class="box-header with-border"><h3 class="box-title">Penandatangan dan Kop Surat</h3></div><div class="box-body"><div class="row"><div class="col-sm-6 form-group"><label for="bunker-SignatoryTitle">Jabatan Penandatangan</label><input id="bunker-SignatoryTitle" name="SignatoryTitle" maxlength="200" class="form-control" value="<?= html_escape($value('SignatoryTitle')) ?>" required></div><div class="col-sm-6 form-group"><label for="bunker-Signatory">Nama Penandatangan</label><input id="bunker-Signatory" name="Signatory" maxlength="200" class="form-control" value="<?= html_escape($value('Signatory')) ?>" required></div></div>
<details><summary style="cursor:pointer;margin-bottom:14px">Alamat perusahaan pada footer kop</summary><div class="row"><?php foreach(array('IssuerName'=>array('Nama Perusahaan pada Kop',200),'FooterBranch'=>array('Cabang / Unit Penerbit',200),'IssuerPhone'=>array('Telepon',100),'IssuerWebsite'=>array('Website',150)) as $k=>$field): ?><div class="col-sm-6 form-group"><label for="bunker-<?= $k ?>"><?= $field[0] ?></label><input id="bunker-<?= $k ?>" name="<?= $k ?>" maxlength="<?= $field[1] ?>" class="form-control" value="<?= html_escape($value($k)) ?>" <?= $k==='IssuerName'?'required':'' ?>></div><?php endforeach; ?><div class="col-sm-12 form-group"><label for="bunker-IssuerAddress">Alamat pada Kop</label><textarea id="bunker-IssuerAddress" name="IssuerAddress" maxlength="500" rows="2" class="form-control"><?= html_escape($value('IssuerAddress')) ?></textarea></div></div></details>
<button class="btn btn-primary" id="bunker-save" disabled>Simpan &amp; Preview Surat</button></div></div></form>
<div class="box"><div class="box-body table-responsive"><table class="table"><thead><tr><th>Nomor Surat</th><th>Tanggal</th><th>Area</th><th>Output</th></tr></thead><tbody><?php foreach($requests as $r): ?><tr><td><?= html_escape($r['RequestNo']) ?></td><td><?= html_escape($r['RequestDate']) ?></td><td><?= (int)$r['SpbbID'] ?></td><td><a href="<?= site_url('Pipeline_setup/print_bunker/'.$r['BunkerID']) ?>" target="_blank">View / Cetak</a> &middot; <a href="<?= site_url('Pipeline_setup/print_bunker/'.$r['BunkerID']).'?pdf=1' ?>">PDF</a> · <a href="<?= site_url('Pipeline_documents/edit/bunker/'.(int)$r['BunkerID']) ?>">Edit</a><?php $action_type='bunker';$action_id=(int)$r['BunkerID'];$this->load->view('pipeline/document_delete',compact('action_type','action_id')); ?></td></tr><?php endforeach; ?><?php if(!$requests): ?><tr><td colspan="4">Belum ada surat permohonan.</td></tr><?php endif; ?></tbody></table></div></div></section></div>
<script>(function(){var area=document.getElementById('bunker-area'),vessel=document.getElementById('bunker-vessel'),date=document.getElementById('bunker-RequestDate'),number=document.getElementById('bunker-number'),help=document.getElementById('bunker-number-help'),save=document.getElementById('bunker-save'),request=0;var endpoint=<?= json_encode(site_url('Pipeline_setup/bunker_number_preview'),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,masters=<?= json_encode($prefill,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,places=<?= json_encode($places,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
function preview(){var serial=++request;number.value='';save.disabled=true;if(!area.value||!vessel.value||!date.value){help.textContent='Pilih area, kapal dan tanggal surat.';return;}help.textContent='Menghitung nomor surat...';fetch(endpoint+'?'+new URLSearchParams({area:area.value,vessel:vessel.value,date:date.value}).toString(),{credentials:'same-origin',cache:'no-store'}).then(function(r){return r.json();}).then(function(data){if(serial!==request)return;if(!data.ok){help.textContent=data.message||'Nomor surat belum tersedia.';return;}number.value=data.number;help.textContent='Pratinjau nomor. Nomor final dikunci saat penyimpanan agar tidak ganda.';save.disabled=false;}).catch(function(){if(serial===request)help.textContent='Nomor belum dapat dibaca. Periksa koneksi dan coba pilih kapal kembali.';});}
function fillMaster(force){var row=masters[vessel.value]||{};['VesselName','Flag','GrossTonnage','VesselType','CompanyName','MainTank','DailyTank'].forEach(function(k){var input=document.getElementById('bunker-'+k);if(force||!input.value||k==='VesselName'||k==='CompanyName')input.value=row[k]||((vessel.value&&k==='Flag')?'Indonesia':'');});}
function filter(changed){Array.prototype.forEach.call(vessel.options,function(o){if(!o.value)return;o.hidden=o.disabled=o.dataset.area!==area.value;if(o.disabled&&o.selected)vessel.value='';});if(changed){var place=places[area.value]||'';if(place.replace(/\s/g,'').toLowerCase()==='padangbai')place='Padangbai';document.getElementById('bunker-Place').value=place;document.getElementById('bunker-PortName').value=place;document.getElementById('bunker-RecipientPlace').value=place.toUpperCase();}fillMaster(changed);preview();}
area.addEventListener('change',function(){filter(true);});vessel.addEventListener('change',function(){fillMaster(true);preview();});date.addEventListener('change',preview);document.getElementById('bunker-form').addEventListener('submit',function(){save.disabled=true;save.textContent='Menyimpan surat...';});filter(false);})();</script>
